update country_flag_history set date_start = '1919-03-26', date_end = '1936-03-25', label_fr = 'Philippines sous administration américaine (1919-1936)', label_en = 'US-administered Philippines (1919–1936)', notes_fr = 'Interdit par les autorités américaines de 1907 à 1919, le drapeau est de nouveau autorisé en 1919 ; il est alors fabriqué avec le bleu foncé du drapeau des États-Unis.', notes_en = 'Banned by the US authorities from 1907 to 1919, the flag was allowed again in 1919; it was then made with the dark blue of the US flag.', image_url = '/flags/history/ph-1919.svg' where id = 2233 and iso_code = 'ph';
update country_flag_history set label_fr = 'Commonwealth puis République (1936-1985)', label_en = 'Commonwealth, then Republic (1936–1985)', notes_fr = 'Le Commonwealth fixe en 1936 un dessin officiel, avec le bleu du drapeau américain ; il devient le drapeau de la République indépendante en 1946.', notes_en = 'The Commonwealth set an official design in 1936, with the blue of the US flag; it became the flag of the independent Republic in 1946.' where id = 2448 and iso_code = 'ph';
